BEGIN;
CREATE OR REPLACE FUNCTION risk_reconciliation_reject_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'risk reconciliation fixture history is immutable'; END $$;
CREATE TABLE IF NOT EXISTS risk_source_observations (observation_hash text PRIMARY KEY CHECK(observation_hash ~ '^[a-f0-9]{64}$'),tenant_id text NOT NULL,account_id text NOT NULL,scope_key text NOT NULL,source_id text NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,account_id,scope_key,source_id,observation_hash));
CREATE TABLE IF NOT EXISTS risk_input_manifests (manifest_hash text PRIMARY KEY CHECK(manifest_hash ~ '^[a-f0-9]{64}$'),tenant_id text NOT NULL,account_id text NOT NULL,scope_key text NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS risk_snapshots (snapshot_hash text PRIMARY KEY CHECK(snapshot_hash ~ '^[a-f0-9]{64}$'),tenant_id text NOT NULL,account_id text NOT NULL,scope_key text NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS risk_reservations (reservation_hash text PRIMARY KEY CHECK(reservation_hash ~ '^[a-f0-9]{64}$'),tenant_id text NOT NULL,account_id text NOT NULL,scope_key text NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,account_id,scope_key,reservation_hash));
CREATE TABLE IF NOT EXISTS risk_execution_attempts (receipt_hash text PRIMARY KEY CHECK(receipt_hash ~ '^[a-f0-9]{64}$'),tenant_id text NOT NULL,account_id text NOT NULL,scope_key text NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS risk_reconciliation_receipts (receipt_hash text PRIMARY KEY CHECK(receipt_hash ~ '^[a-f0-9]{64}$'),tenant_id text NOT NULL,account_id text NOT NULL,scope_key text NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS risk_test_center_bundles (run_id text PRIMARY KEY REFERENCES agent_test_center_runs(run_id),manifest_hash text NOT NULL REFERENCES risk_input_manifests(manifest_hash),snapshot_hash text NOT NULL REFERENCES risk_snapshots(snapshot_hash),reservation_hash text NOT NULL REFERENCES risk_reservations(reservation_hash),created_at timestamptz NOT NULL DEFAULT now());
DO $$ DECLARE item text; BEGIN FOREACH item IN ARRAY ARRAY['risk_source_observations','risk_input_manifests','risk_snapshots','risk_reservations','risk_execution_attempts','risk_reconciliation_receipts','risk_test_center_bundles'] LOOP EXECUTE format('DROP TRIGGER IF EXISTS %I_immutable ON %I', item,item); EXECUTE format('CREATE TRIGGER %I_immutable BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION risk_reconciliation_reject_mutation()', item,item); END LOOP; END $$;
COMMIT;
